import { createHash } from 'node:crypto'
import { selectInspectionRun, selectFaultChild, faultReportSource, mainFaultReportSource, selectSavedSecurityReport } from './security-report-source.mjs'

type RecordValue = Record<string, any>
export const name = 'security-report-runtime'
export const inject = ['tools', 'attachments', 'sessionQuery', 'mcpSessionManager']
const record = (value: any): value is RecordValue => value !== null && typeof value === 'object' && !Array.isArray(value)

/** MCP 的公开 JSON 回执；工具错误、业务错误和无法解码均不成为报告。 */
export function reportValue(value: any): RecordValue {
  if (value?.isError === true) throw new Error('报告读取失败，未生成下载文件')
  if (record(value?.structuredContent)) value = value.structuredContent
  else if (Array.isArray(value?.content)) {
    const text = value.content.filter((part: any) => part?.type === 'text').map((part: any) => part.text).join('')
    try { value = JSON.parse(text) } catch { throw new Error('报告服务未返回完整的结构化产物') }
  }
  if (record(value) && Object.hasOwn(value, 'code')) {
    if (String(value.code) !== '200') throw new Error('报告服务返回业务失败，未生成下载文件')
    value = value.data
  }
  // 平台组合查询使用ok/result；失败或缺失产物不能作为已读取的报告。
  if (record(value) && Object.hasOwn(value, 'ok')) {
    if (value.ok !== true || !record(value.result)) throw new Error('平台报告读取失败或缺少完整产物')
    value = value.result
  }
  if (!record(value)) throw new Error('报告产物回执无效')
  return value
}

export function requireReportRequest(exec: any) {
  const agent = exec?.agent, session = agent?.session
  if (!agent?.id || session?.id !== agent.id || (session.header?.delegationDepth ?? 0) !== 0
    || typeof session.snapshotEvents !== 'function') throw new Error('报告仅能由当前真实主会话生成')
  const events = session.snapshotEvents()
  const user = events.findLast((event: any) => event?.type === 'user/message' && event.data?.source?.kind === 'user')
  const content = user?.data?.content
  const text = typeof content === 'string' ? content : Array.isArray(content)
    ? content.filter((part: any) => part?.type === 'text').map((part: any) => part.text).join('') : ''
  const requested = /(?:生成|导出|下载|保存|提供|交付|输出|给我)[\s\S]{0,40}(?:报告|HTML)|(?:报告|HTML)[\s\S]{0,20}(?:生成|导出|下载|保存)|(?:执行|开始|运行)[\s\S]{0,20}巡检/iu.test(text)
  if (!user?.data?.id || !requested || /(?:不要|禁止|无需|暂不|先不|别)[\s\S]{0,8}(?:生成|导出|下载|保存)(?:[\s\S]{0,8}报告)?/u.test(text)) {
    throw new Error('当前请求没有报告生成或下载意图，未写入文件')
  }
  return { agent, events }
}

/** 只取原报告或已完成的故障分析；不启动巡检、诊断、探测或处置。 */
export function apply(ctx: any) {
  ctx.tools.register({
    name: 'export_security_report',
    description: '将当前会话真实巡检原HTML或只读故障分析保存为可预览、下载的HTML。主助手已取得或补充SOC证据时，必须用analysis传完整可见分析正文，由入口绑定真实只读回执；不能只导出旧子任务的能力缺口。未补证且已有完整故障子结果时可省略analysis。再次下载优先传上次真实attachment_id，仅复用原文件，不重查或再委派。不能传HTML文档、任意路径、URL或其他会话；生成不等于修复或已下载。',
    parameters: { type: 'object', additionalProperties: false, required: ['kind'], properties: {
      kind: { type: 'string', enum: ['inspection', 'fault'] },
      run_id: { type: 'string', description: '可选，仅巡检：本会话实际回执的原运行编号；省略核验最近真实启动的原运行，仅完成时导出，不回退其他运行。' },
      child_id: { type: 'string', description: '可选，仅故障：明确导出本会话指定已完成子分析；不得与analysis混用。主助手已补证时应改用analysis。' },
      analysis: { type: 'string', minLength: 1, maxLength: 65536, description: '仅故障：主助手依据本会话实际SOC只读回执整理的完整可见报告正文，含事实、推断、证据缺口、未执行建议；不是HTML或隐藏reasoning。语义分析由模型负责，来源由入口核对。' },
      evidence_call_ids: { type: 'array', minItems: 1, maxItems: 32, uniqueItems: true, items: { type: 'string', minLength: 1 }, description: '可选，配合analysis绑定本会话真实只读查询调用；省略自动选择最近实际取证批次。不让用户填写编号，不以用户材料冒充原生回执。' },
      attachment_id: { type: 'string', pattern: '^sha256:[a-f0-9]{64}$', description: '再次下载时仅传本会话上次真实导出回执的attachment_id；与run_id/child_id/analysis/evidence_call_ids互斥，不新生成或取证。' },
    } },
    output: {
      schema: { type: 'object' },
      render: (_args: any, value: any) => [{ type: 'text', text: JSON.stringify(value) }],
      presentationMeta: (_args: any, value: any) => value,
    },
    async execute(args: RecordValue, exec: any) {
      const { agent, events } = requireReportRequest(exec)
      if (!record(args) || !['inspection', 'fault'].includes(args.kind)
        || Object.keys(args).some(key => !['kind', 'run_id', 'child_id', 'analysis', 'evidence_call_ids', 'attachment_id'].includes(key))
        || args.run_id !== undefined && typeof args.run_id !== 'string'
        || args.child_id !== undefined && typeof args.child_id !== 'string'
        || args.kind === 'inspection' && ['child_id', 'analysis', 'evidence_call_ids'].some(key => args[key] !== undefined)
        || args.kind === 'fault' && args.run_id !== undefined
        || args.analysis !== undefined && (typeof args.analysis !== 'string' || !args.analysis.trim() || args.analysis.length > 65536)
        || args.evidence_call_ids !== undefined && (args.analysis === undefined || !Array.isArray(args.evidence_call_ids)
          || args.evidence_call_ids.length < 1 || args.evidence_call_ids.length > 32 || args.evidence_call_ids.some((id: any) => typeof id !== 'string' || !id.trim())
          || new Set(args.evidence_call_ids).size !== args.evidence_call_ids.length)
        || args.analysis !== undefined && args.child_id !== undefined
        || args.attachment_id !== undefined && (typeof args.attachment_id !== 'string' || !/^sha256:[a-f0-9]{64}$/u.test(args.attachment_id)
          || ['run_id', 'child_id', 'analysis', 'evidence_call_ids'].some(key => args[key] !== undefined))) throw new Error('报告类型或来源参数不符合合同')
      exec.signal?.throwIfAborted()
      const saved = selectSavedSecurityReport(agent.id, events, args.kind, args.attachment_id)
      if (args.attachment_id !== undefined && !saved) throw new Error('本会话没有该真实已导出报告，不猜测附件或文件路径')
      if (args.attachment_id !== undefined || args.kind === 'fault' && args.analysis === undefined && args.child_id === undefined && saved && !saved.has_new_source) {
        return { ...saved!.value, message: '已复用本会话原HTML文件，未重新取证、分析或生成。可预览或下载；文件读取时仍核对原始字节和SHA-256。' }
      }
      let html: string, source: RecordValue, filename: string
      let expectedInspectionBytes: number | undefined
      if (args.kind === 'inspection') {
        const canonical = (tool: string) => {
          for (const raw of ['inspection_status', 'inspection_baseline', 'inspection_vulnerabilities', 'inspection_reachability', 'inspection_routine', 'inspection_deep', 'get_composition_run', 'get_composition_artifact']) {
            if (ctx.mcpSessionManager.resolveTool('inspection-compositions', raw) === tool) return `mcp__inspection-compositions__${raw}`
          }
          return undefined
        }
        const selected = selectInspectionRun(events, args.run_id, canonical)
        const query = ctx.mcpSessionManager.resolveTool('inspection-compositions', 'get_composition_run')
        if (!query || !ctx.tools.get(query, agent)) throw new Error('当前没有同次巡检终态读取入口')
        // 使用公开SDK策略管线后的canonical值，不以Session中的裁剪/分段展示文本判终态。
        const state = await ctx.tools.execute({ name: query,
          callId: `${exec.callId}:status`, rootCallId: exec.rootCallId, parent: exec.token,
          arguments: { run_id: selected.run_id }, agent, signal: exec.signal })
        for (const context of state.additionalContexts ?? []) exec.deferContext(context)
        exec.signal?.throwIfAborted()
        if (state.isError) throw new Error('原巡检终态读取失败，未导出报告')
        const run = reportValue(state.value)
        if (run.run_id !== selected.run_id || run.composition_id !== selected.workflow
          || run.workflow !== undefined && run.workflow !== selected.workflow) throw new Error('巡检结果与本会话原始运行或流程不一致')
        // result.status是业务完整性，不能代替外层Run执行状态。
        if (run.status !== 'completed') throw new Error('原巡检尚未成功结束，不能将运行中或失败状态导出为已完成报告。')
        const reports = Array.isArray(run.artifacts) ? run.artifacts.filter((item: any) => item?.id === 'report') : []
        const report = reports[0]
        if (reports.length !== 1 || typeof report.filename !== 'string' || !/\.html$/iu.test(report.filename)
          || typeof report.contentType !== 'string' || !/^text\/html(?:\s*;|\s*$)/iu.test(report.contentType)
          || !Number.isSafeInteger(report.bytes) || report.bytes <= 0) throw new Error('原巡检未返回唯一、非空的HTML报告产物')
        expectedInspectionBytes = report.bytes
        const actual = ctx.mcpSessionManager.resolveTool('inspection-compositions', 'get_composition_artifact')
        if (!actual || !ctx.tools.get(actual, agent)) throw new Error('当前没有同次巡检报告读取入口')
        const result = await ctx.tools.execute({ name: actual,
          callId: `${exec.callId}:report`, rootCallId: exec.rootCallId, parent: exec.token,
          arguments: { run_id: selected.run_id, artifactId: report.id }, agent, signal: exec.signal })
        for (const context of result.additionalContexts ?? []) exec.deferContext(context)
        exec.signal?.throwIfAborted()
        if (result.isError) throw new Error('原巡检报告读取失败，未重新启动巡检')
        const artifact = reportValue(result.value)
        if (typeof artifact.body !== 'string' || !/^text\/html(?:\s*;|$)/iu.test(artifact.contentType ?? '')
          || !/\.html$/iu.test(artifact.filename ?? '')) throw new Error('原运行尚无可导出的完整HTML报告')
        if (artifact.filename !== report.filename || artifact.contentType !== report.contentType) throw new Error('原报告与同次产物元数据不一致')
        html = artifact.body
        source = { kind: 'inspection', run_id: selected.run_id, artifact_id: report.id,
          original_filename: artifact.filename, original_sha256: createHash('sha256').update(html).digest('hex') }
        filename = `inspection-report-${selected.run_id}.html`
      } else if (args.analysis !== undefined) {
        const report = mainFaultReportSource(agent.id, events, args.analysis, args.evidence_call_ids)
        html = report.html
        source = { ...report.source }
        filename = `fault-report-${report.source.content_sha256.slice(0, 16)}.html`
      } else {
        const selected = selectFaultChild(agent.id, events, args.child_id)
        const snapshot = await ctx.sessionQuery.readSession(selected.childId)
        exec.signal?.throwIfAborted()
        // 读取期间重新核对本会话的真实委派，不能以过时的来源选择继续生成。
        const fresh = selectFaultChild(agent.id, agent.session.snapshotEvents(), args.child_id)
        if (fresh.childId !== selected.childId || fresh.delegateCallId !== selected.delegateCallId || fresh.noticeSeq !== selected.noticeSeq) throw new Error('故障分析来源已变化，请核对原结果')
        const report = faultReportSource(fresh, snapshot)
        html = report.html
        source = { ...report.source }
        filename = `fault-report-${selected.childId}.html`
      }
      if (!/^\s*<!doctype\s+html\b/iu.test(html) || !/<html\b/iu.test(html) || !/<\/html>\s*$/iu.test(html)) {
        throw new Error('报告不是完整HTML文档，未把片段冒充完整报告')
      }
      const data = Buffer.from(html, 'utf8')
      if (expectedInspectionBytes !== undefined && data.byteLength !== expectedInspectionBytes) throw new Error('原报告字节数与同次产物元数据不一致，未截断交付')
      if (data.byteLength > 32 * 1024 * 1024) throw new Error('报告超过原生完整文件预览的32MiB默认上限，未截断交付')
      exec.signal?.throwIfAborted()
      const attachment = await ctx.attachments.saveFile({ name: filename, data })
      const path = ctx.attachments.fileHostPath(attachment)
      if (!path || attachment.bytes !== data.byteLength) throw new Error('HTML已保存但当前文件后端不能提供可核对的下载文件')
      exec.signal?.throwIfAborted()
      return { schema_version: 'security-report/v1', kind: args.kind, session_id: agent.id,
        file_path: path, filename: attachment.name, content_type: 'text/html; charset=utf-8', bytes: attachment.bytes,
        sha256: createHash('sha256').update(data).digest('hex'), attachment_id: attachment.attachmentId,
        source, generated_at: new Date().toISOString(),
        message: 'HTML报告文件已生成。可在本次报告卡片预览或下载HTML；生成文件不表示故障已修复或巡检全部正常。' }
    },
  })
}

export interface InspectionReportBinding {
  readonly run_id: string
  readonly workflow: string
}

/** 只能由 selectFaultChild 从当前父会话原生日志派生，不接收模型提供的绑定。 */
export interface FaultReportBinding {
  readonly parentId: string
  readonly childId: string
  readonly childCreatedAt: number
  readonly delegateCallId: string
  readonly request: string
  readonly userMessageId: string
  readonly requestSeq: number
  readonly delegateSeq: number
  readonly receiptSeq: number
  readonly noticeSeq: number
  readonly noticeTime: number
}

export interface FaultReportSource {
  readonly kind: 'fault-readonly'
  readonly parent_session_id: string
  readonly child_session_id: string
  readonly child_created_at: number
  readonly delegate_call_id: string
  readonly user_message_id: string
  readonly request_seq: number
  readonly delegate_seq: number
  readonly receipt_seq: number
  readonly notice_seq: number
  readonly result_seq: number
  readonly completed_turn: number
  readonly completed_seq: number
  readonly completed_at: string
  readonly request_sha256: string
  readonly content_sha256: string
  readonly source_sha256: string
}

/** 仅从本会话真实成功启动回执绑定run/workflow；调用方再以完整canonical回执校验终态及产物。 */
export function selectInspectionRun(
  events: readonly unknown[],
  runId?: string,
  canonicalName?: (name: string) => string | undefined,
): InspectionReportBinding

/** 默认最近已完成故障来源；指定 childId 也必须存在本会话原生直接子证据。 */
export function selectFaultChild(
  parentId: string,
  events: readonly unknown[],
  childId?: string,
): FaultReportBinding

/** snapshot 为 sessionQuery.readSession 的原生返回；正文只取成功终态的可见文本。 */
export function faultReportSource(
  binding: FaultReportBinding,
  snapshot: unknown,
): { html: string; source: FaultReportSource }

export interface MainFaultEvidence {
  readonly call_id: string
  readonly tool_name: string
  readonly call_seq: number
  readonly result_seq: number
  readonly is_error: boolean
  readonly user_message_id: string
  readonly request_seq: number
  readonly receipt_projection: 'native-tool-result.visible-text/v1'
  readonly receipt_sha256: string
}

export interface MainFaultReportSource {
  readonly kind: 'fault-main-readonly'
  readonly parent_session_id: string
  readonly user_message_id: string
  readonly request_seq: number
  readonly evidence: readonly MainFaultEvidence[]
  readonly evidence_until_seq: number
  readonly evidence_until_utc: string
  readonly requests: readonly {
    readonly user_message_id: string
    readonly request_seq: number
    readonly request_sha256: string
  }[]
  readonly receipt_hash_scope: string
  readonly request_sha256: string
  readonly content_sha256: string
  readonly source_sha256: string
}

/** Root归属由Runtime核对；正文仅为主助手可见分析，来源只能绑定真实本会话只读回执。 */
export function mainFaultReportSource(
  parentId: string,
  events: readonly unknown[],
  analysis: string,
  evidenceCallIds?: readonly string[],
  canonicalName?: (name: string) => string | undefined,
): { html: string; source: MainFaultReportSource }

export interface SavedSecurityReport {
  readonly value: Record<string, any>
  readonly receipt_seq: number
  readonly has_new_source: boolean
}

/** 需原生export成功配对回执；不透明MCP别名会保守阻止默认旧附件复用。 */
export function selectSavedSecurityReport(
  parentId: string,
  events: readonly unknown[],
  kind: 'inspection' | 'fault',
  attachmentId?: string,
): SavedSecurityReport | undefined

import { createHash } from 'node:crypto'

// 纯函数：调用方只传入原生 Session 日志和 sessionQuery 返回的快照。
// 不读取文件、不调用工具、不执行报告文字，也不维护另一份运行账本。
// 主助手正文是可见语义分析；来源只从本 Root 会话的真实回执绑定，不从正文解析。
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value)
const identifier = value => typeof value === 'string' && value.length > 0
  && value.length <= 512 && !/[\s\u0000-\u001f\u007f]/u.test(value)
const integer = value => Number.isSafeInteger(value) && value >= 0
const fail = message => { throw new Error(message) }
const hash = value => createHash('sha256').update(value, 'utf8').digest('hex')
const escape = value => String(value).replace(/[&<>"']/g, char => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
})[char])
const textOnly = content => Array.isArray(content) && content.length > 0
  && content.every(part => part?.type === 'text' && typeof part.text === 'string')
  ? content.map(part => part.text).join('') : undefined
const visibleText = content => Array.isArray(content)
  ? content.filter(part => part?.type === 'text' && typeof part.text === 'string').map(part => part.text).join('')
  : ''
const parseObject = text => {
  if (typeof text !== 'string') return undefined
  try { const value = JSON.parse(text); return object(value) ? value : undefined } catch { return undefined }
}

function ownEvents(input) {
  if (!Array.isArray(input) || input.some((event, index) => !object(event)
    || !integer(event.seq) || typeof event.type !== 'string' || !object(event.data)
    || index > 0 && event.seq <= input[index - 1].seq)) {
    fail('报告来源必须是按序、无重复序号的原生会话事件。')
  }
  // Fork 继承前缀不能给当前会话建立新的运行/直接子绑定。
  const cut = input.findLastIndex(event => event.type === 'session/end-seed' && event.data.inherited === true)
  return input.slice(cut + 1)
}

function successfulPairs(events, includeErrors = false) {
  const calls = new Map(), receipts = new Map()
  for (const event of events) {
    if (event.type === 'tool/call' && identifier(event.data.callId)) {
      const list = calls.get(event.data.callId) ?? []
      list.push(event); calls.set(event.data.callId, list)
    } else if (event.type === 'tool/result' && identifier(event.data.message?.toolCallId)) {
      const list = receipts.get(event.data.message.toolCallId) ?? []
      list.push(event); receipts.set(event.data.message.toolCallId, list)
    }
  }
  const pairs = []
  for (const [callId, entries] of calls) {
    const results = receipts.get(callId) ?? []
    if (entries.length !== 1 || results.length !== 1) continue
    const call = entries[0], receipt = results[0], message = receipt.data.message
    if (call.seq >= receipt.seq || typeof call.data.name !== 'string'
      || !integer(call.data.turn) || !integer(call.data.step)
      || call.data.turn !== receipt.data.turn || call.data.step !== receipt.data.step
      || message?.role !== 'tool' || message.source?.kind !== 'tool'
      || message.source.callId !== callId || message.toolCallId !== callId
      || message.isError !== undefined && typeof message.isError !== 'boolean') continue
    const isError = message.isError === true || receipt.data.error !== undefined
    if (!includeErrors && isError) continue
    if (receipt.sourceEventSeqs !== undefined && (!Array.isArray(receipt.sourceEventSeqs)
      || !receipt.sourceEventSeqs.includes(call.seq)
      || receipt.sourceEventSeqs.some(seq => !integer(seq) || seq >= receipt.seq))) continue
    const args = parseObject(call.data.arguments)
    if (args) pairs.push({ call, receipt, args, isError })
  }
  return pairs
}

function inspectionValue(message) {
  let value = parseObject(textOnly(message.content))
  for (let depth = 0; object(value) && depth < 6; depth++) {
    if (value.isError === true || value.ok !== undefined && value.ok !== true) return undefined
    if (value.structuredContent !== undefined) { value = value.structuredContent; continue }
    if (Array.isArray(value.content)) { value = parseObject(textOnly(value.content)); continue }
    if (value.code !== undefined) {
      if (String(value.code) !== '200') return undefined
      value = value.data; continue
    }
    // 先认外层 Run，绝不把它的 result.status（业务完整性）当执行状态。
    if (identifier(value.run_id)) return value
    if (object(value.result)) { value = value.result; continue }
    if (object(value.run)) { value = value.run; continue }
    return undefined
  }
  return undefined
}

const inspectionTools = new Map(['status', 'baseline', 'vulnerabilities', 'reachability', 'routine', 'deep']
  .map(kind => [`mcp__inspection-compositions__inspection_${kind}`, `inspection-${kind}`]))
/** 仅从本会话真实成功调用绑定原运行；终态不能取自可能被spill裁剪的展示文本。 */
export function selectInspectionRun(input, runId, canonicalName = name => name) {
  if (runId !== undefined && !identifier(runId)) fail('巡检报告运行标识无效。')
  if (typeof canonicalName !== 'function') fail('巡检工具来源解析器无效。')
  const events = ownEvents(input), origins = new Map()
  for (const pair of successfulPairs(events)) {
    const workflow = inspectionTools.get(canonicalName(pair.call.data.name))
    if (!workflow) continue
    const value = inspectionValue(pair.receipt.data.message)
    if (!value) continue
    if (value.composition_id !== undefined && value.composition_id !== workflow
      || value.workflow !== undefined && value.workflow !== workflow) continue
    const previous = origins.get(value.run_id)
    if (previous && previous.workflow !== workflow) fail('同一巡检运行出现冲突的原始启动来源。')
    origins.set(value.run_id, { runId: value.run_id, workflow, seq: pair.receipt.seq })
  }
  const origin = runId !== undefined ? origins.get(runId)
    : [...origins.values()].sort((left, right) => right.seq - left.seq)[0]
  if (!origin) fail('本会话没有可核验的巡检启动回执，不能借外部运行标识导出。')
  return Object.freeze({ run_id: origin.runId, workflow: origin.workflow })
}

/** 直接子来源必须先在父原生日志中证实，调用方随后才能读取该 childId。 */
export function selectFaultChild(parentId, input, childId) {
  if (!identifier(parentId) || childId !== undefined && (!identifier(childId) || childId === parentId)) {
    fail('故障报告主/子会话标识无效。')
  }
  const events = ownEvents(input), pairs = successfulPairs(events)
    .filter(pair => pair.call.data.name === 'delegate_fault_analysis')
  const candidates = []
  for (const catalog of events.filter(event => event.type === 'subagent/catalog')) {
    const data = catalog.data, id = data.childId
    if (childId !== undefined && id !== childId) continue
    if (!identifier(id) || id === parentId || data.version !== 0 || data.mode !== 'continuable'
      || !integer(data.childCreatedAt)) continue
    const catalogs = events.filter(event => event.type === 'subagent/catalog' && event.data.childId === id)
    if (catalogs.length !== 1) fail('故障子任务目录身份重复或冲突，不能选择报告来源。')
    const matches = pairs.filter(pair => textOnly(pair.receipt.data.message.content) === `started subagent ${id}`)
    if (matches.length !== 1) continue
    const { call, receipt, args } = matches[0]
    if (!(call.seq < catalog.seq && catalog.seq < receipt.seq)
      || typeof args.prompt !== 'string' || !args.prompt.trim()) continue
    const notices = events.filter(event => event.type === 'user/message' && event.data.role === 'user'
      && event.data.source?.kind === 'subagent-settled' && event.data.source.form === 'notice'
      && typeof event.data.source.summary === 'string' && event.data.source.senderSessionId === id
      && event.seq > receipt.seq)
    // 重复投递不使只读导出失效，也不能把旧任务伪装成最近新任务。
    const notice = notices[0]
    if (!notice || !integer(notice.time) || notice.time < data.childCreatedAt) continue
    const user = events.findLast(event => event.seq < call.seq && event.type === 'user/message'
      && event.data.role === 'user' && event.data.source?.kind === 'user')
    const request = visibleText(user?.data.content)
    if (!user || !identifier(user.data.id) || !request.trim()) continue
    candidates.push(Object.freeze({ parentId, childId: id, childCreatedAt: data.childCreatedAt,
      delegateCallId: call.data.callId, request, userMessageId: user.data.id, requestSeq: user.seq,
      delegateSeq: call.seq, receiptSeq: receipt.seq, noticeSeq: notice.seq, noticeTime: notice.time }))
  }
  candidates.sort((left, right) => right.noticeSeq - left.noticeSeq)
  if (!candidates.length) fail('本会话没有已证实完成的故障分析委派，不能读取任意会话或导出启动回执。')
  const selected = candidates[0]
  if (childId === undefined && rootReadonlyPairs(events).some(pair => pair.receipt.seq > selected.noticeSeq)) {
    fail('主助手已有更新证据，请用analysis导出完整分析；不能仅保存补证前的旧子任务正文。')
  }
  return selected
}

function startupOnly(body) {
  const value = body.trim()
  return /^started subagent \S+$/u.test(value)
    || /^已启动故障分析子智能体[。.!！]?(?:\s*任务[：:][^\n]*)?(?:\s*结果将在任务结束后返回[。.!！]?)?$/u.test(value)
}

/** 渲染既有只读分析；不进行新的诊断、推理、处置或外部持久化。 */
export function faultReportSource(binding, snapshot) {
  if (!object(binding) || !identifier(binding.parentId) || !identifier(binding.childId)
    || binding.parentId === binding.childId || !identifier(binding.delegateCallId)
    || !identifier(binding.userMessageId) || typeof binding.request !== 'string' || !binding.request.trim()
    || !['childCreatedAt', 'requestSeq', 'delegateSeq', 'receiptSeq', 'noticeSeq', 'noticeTime'].every(key => integer(binding[key]))
    || !(binding.requestSeq < binding.delegateSeq && binding.delegateSeq < binding.receiptSeq
      && binding.receiptSeq < binding.noticeSeq)) fail('故障报告缺少受管选择的真实来源绑定。')
  const header = snapshot?.session
  if (!object(header) || header.id !== binding.childId || header.createdAt !== binding.childCreatedAt
    || header.origin !== 'subagent' || header.isSeeded !== false || snapshot.inheritedEventCount !== 0
    || header.delegationDepth !== undefined && header.delegationDepth !== 1
    || header.agentPreset !== undefined && header.agentPreset !== 'security-operations-fault-analysis') {
    fail('故障子会话快照与父目录不一致，或包含继承/其他角色内容。')
  }
  const events = ownEvents(snapshot.events)
  const start = events.findLast(event => event.type === 'turn/start')
  const end = events.findLast(event => event.type === 'turn/end')
  if (!start || !end || !integer(start.data.turn) || end.seq <= start.seq
    || end.data.turn !== start.data.turn || end.data.reason?.kind !== 'completed'
    || !integer(end.time) || end.time < binding.childCreatedAt || end.time > binding.noticeTime
    || events.filter(event => event.type === 'turn/end' && event.data.turn === end.data.turn).length !== 1) {
    fail('故障子任务没有与原生完成通知匹配的成功终态，不能导出运行中、失败或后续改动的结果。')
  }
  const tail = events.filter(event => event.seq > start.seq && event.seq < end.seq
    && ['assistant/message', 'tool/call', 'tool/result', 'user/message', 'assistant/attempt'].includes(event.type)).at(-1)
  const message = tail?.data?.message
  if (tail?.type !== 'assistant/message' || tail.data.turn !== end.data.turn || tail.data.interrupted === true
    || message?.role !== 'assistant' || message.source?.kind !== 'model'
    || !identifier(message.id) || typeof message.source.provider !== 'string' || !message.source.provider
    || typeof message.source.model !== 'string' || !message.source.model
    || !Array.isArray(message.content) || message.content.some(part => !object(part)
      || !['text', 'reasoning'].includes(part.type) || typeof part.text !== 'string')) {
    fail('故障子任务没有真实、完整的最终助手正文，不能把工具回执或未完成片段当报告。')
  }
  // reasoning 块不是用户可见正文，永不写入报告。
  const body = visibleText(message.content)
  if (!body.trim() || startupOnly(body)) fail('故障分析结果为空或只有启动通知，不能生成内容报告。')
  const sourceBase = {
    kind: 'fault-readonly', parent_session_id: binding.parentId, child_session_id: binding.childId,
    child_created_at: binding.childCreatedAt, delegate_call_id: binding.delegateCallId,
    user_message_id: binding.userMessageId, request_seq: binding.requestSeq, delegate_seq: binding.delegateSeq,
    receipt_seq: binding.receiptSeq, notice_seq: binding.noticeSeq, result_seq: tail.seq,
    completed_turn: end.data.turn, completed_seq: end.seq, completed_at: new Date(end.time).toISOString(),
    request_sha256: hash(binding.request), content_sha256: hash(body),
  }
  const source = Object.freeze({ ...sourceBase, source_sha256: hash(JSON.stringify(sourceBase)) })
  const rows = [
    ['报告性质', '只读取证与分析；不是外部平台诊断归档，不表示问题已修复或已执行处置'],
    ['分析完成时间（UTC）', source.completed_at], ['主会话', source.parent_session_id],
    ['故障子会话', source.child_session_id], ['委派调用', source.delegate_call_id],
    ['原用户消息', source.user_message_id], ['请求事件序号', source.request_seq],
    ['委派/启动回执/完成通知序号', `${source.delegate_seq} / ${source.receipt_seq} / ${source.notice_seq}`],
    ['最终正文/成功终态序号', `${source.result_seq} / ${source.completed_seq}`],
    ['原请求 SHA-256', source.request_sha256], ['原正文 SHA-256', source.content_sha256],
    ['来源记录 SHA-256', source.source_sha256],
  ]
  return { html: renderFaultHtml(binding.request, body, rows), source }
}

function renderFaultHtml(request, body, rows, options = {}) {
  const note = options.note ?? '只读取证与分析。原文中的事实、推断、证据缺口与未执行建议均按原文保留；未列出的内容不补造。生成本文件不会重新取证、主动探测、执行处置或证明问题已修复。'
  const bodyTitle = options.bodyTitle ?? '只读取证与分析正文（原文）'
  const html = '<!doctype html>\n<html lang="zh-CN"><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width,initial-scale=1">'
    + '<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; script-src \'none\'; style-src \'unsafe-inline\'; img-src \'none\'; object-src \'none\'; base-uri \'none\'; form-action \'none\'">'
    + '<meta name="referrer" content="no-referrer"><title>故障排查报告（只读取证与分析）</title>'
    + '<style>html{color-scheme:light}body{margin:0;background:#f3f5f7;color:#202a36;font:16px/1.7 system-ui,sans-serif}.paper{max-width:1040px;margin:32px auto;padding:36px;background:white;border:1px solid #dfe5eb;border-radius:12px}h1{font-size:27px;margin:0 0 12px}h2{font-size:20px;margin-top:28px}.note{padding:12px 16px;border-left:4px solid #56728e;background:#edf3f8}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;margin:0}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #dfe5eb;padding:9px 12px;vertical-align:top;text-align:left;overflow-wrap:anywhere}th{width:27%;font-weight:600}@media(max-width:600px){.paper{margin:0;padding:20px;border:0;border-radius:0}th{width:32%}}@media print{body{background:white}.paper{margin:0;max-width:none;border:0;padding:0}}</style>'
    + '</head><body><main class="paper"><h1>故障排查报告</h1>'
    + '<p class="note">' + escape(note) + '</p>'
    + '<section><h2>原用户请求</h2><pre>' + escape(request) + '</pre></section>'
    + '<section><h2>' + escape(bodyTitle) + '</h2><pre>' + escape(body) + '</pre></section>'
    + (options.extra ?? '')
    + '<section><h2>来源与完整性</h2><p>以下标识和哈希用于回溯原始记录；来源可追溯不代表分析结论已被独立验证。</p><table><tbody>'
    + rows.map(([label, value]) => '<tr><th scope="row">' + escape(label) + '</th><td>' + escape(value) + '</td></tr>').join('')
    + '</tbody></table></section></main></body></html>\n'
